create table public.family_requests(id uuid primary key default gen_random_uuid(), ref text not null unique default ('FR-'||substr(replace(gen_random_uuid()::text,'-',''),1,12)), org_id uuid not null references public.organizations(id), school_id uuid not null references public.schools(id), student_id uuid not null references public.students(id), requested_by uuid not null default auth.uid(), kind text not null, body text not null, status text not null default 'processing', response text, rejection_reason text, decided_by uuid, decided_at timestamptz, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
grant select,insert,update on public.family_requests to authenticated; grant all on public.family_requests to service_role;
alter table public.family_requests enable row level security;
create policy family_requests_read on public.family_requests for select to authenticated using((requested_by=auth.uid() and is_guardian_of(student_id) and school_org(school_id)=org_id) or _ad_ok(auth.uid(),school_id,'view') or _ad_ok(auth.uid(),school_id,'view_branch'));
create policy family_requests_create on public.family_requests for insert to authenticated with check(requested_by=auth.uid() and is_guardian_of(student_id) and org_id=school_org(school_id) and exists(select 1 from students s where s.id=student_id and s.school_id=family_requests.school_id) and status='processing' and response is null and rejection_reason is null and decided_by is null and decided_at is null);
create policy family_requests_decide on public.family_requests for update to authenticated using(_ad_ok(auth.uid(),school_id,'decide')) with check(_ad_ok(auth.uid(),school_id,'decide'));
create table public.family_request_history(id uuid primary key default gen_random_uuid(), request_id uuid not null references public.family_requests(id), actor uuid not null default auth.uid(), status text not null, response text, rejection_reason text, created_at timestamptz not null default now());
grant select,insert on public.family_request_history to authenticated; grant all on public.family_request_history to service_role;
alter table public.family_request_history enable row level security;
create policy family_history_read on public.family_request_history for select to authenticated using(exists(select 1 from family_requests r where r.id=request_id));
create policy family_history_insert on public.family_request_history for insert to authenticated with check(actor=auth.uid() and exists(select 1 from family_requests r where r.id=request_id and ((r.requested_by=auth.uid() and is_guardian_of(r.student_id)) or _ad_ok(auth.uid(),r.school_id,'decide'))));
create or replace function public._family_request_guard() returns trigger language plpgsql set search_path=public as $$ begin
if new.kind not in ('mother_account','withdrawal','data_change') or length(trim(new.body))<3 or length(new.body)>10000 then raise exception 'بيانات الطلب غير صالحة'; end if;
if new.status not in ('processing','accepted','rejected') then raise exception 'حالة غير صالحة'; end if;
if tg_op='INSERT' then new.requested_by:=auth.uid(); new.status:='processing'; new.response:=null; new.rejection_reason:=null; new.decided_by:=null; new.decided_at:=null;
else
if (new.id,new.ref,new.org_id,new.school_id,new.student_id,new.requested_by,new.kind,new.body,new.created_at) is distinct from (old.id,old.ref,old.org_id,old.school_id,old.student_id,old.requested_by,old.kind,old.body,old.created_at) then raise exception 'لا يسمح بتغيير هوية أو نطاق الطلب'; end if;
if old.status<>'processing' then raise exception 'تمت معالجة الطلب بالفعل'; end if;
if new.status='rejected' and length(trim(coalesce(new.rejection_reason,'')))<3 then raise exception 'سبب الرفض مطلوب'; end if;
if new.status in ('accepted','rejected') and length(trim(coalesce(new.response,'')))<3 then raise exception 'رد الإدارة مطلوب'; end if;
new.decided_by:=auth.uid(); new.decided_at:=now(); end if; new.updated_at:=now(); return new; end $$;
create trigger family_request_guard before insert or update on public.family_requests for each row execute function public._family_request_guard();
create or replace function public._family_request_log() returns trigger language plpgsql set search_path=public as $$ begin insert into family_request_history(request_id,actor,status,response,rejection_reason) values(new.id,auth.uid(),new.status,new.response,new.rejection_reason); return new; end $$;
create trigger family_request_log after insert or update on public.family_requests for each row execute function public._family_request_log();
create or replace function public.family_request_create(_student uuid,_kind text,_body text) returns uuid language plpgsql security invoker set search_path=public as $$ declare _id uuid; _school uuid; begin select school_id into _school from students where id=_student; if _school is null or not is_guardian_of(_student) then raise exception 'غير مصرح'; end if; insert into family_requests(org_id,school_id,student_id,kind,body) values(school_org(_school),_school,_student,_kind,_body) returning id into _id; return _id; end $$;
create or replace function public.family_request_decide(_id uuid,_status text,_response text,_reason text default null) returns void language plpgsql security invoker set search_path=public as $$ begin update family_requests set status=_status,response=_response,rejection_reason=_reason where id=_id; if not found then raise exception 'غير مصرح أو الطلب غير موجود'; end if; end $$;
revoke all on function public.family_request_create(uuid,text,text),public.family_request_decide(uuid,text,text,text),public._family_request_guard(),public._family_request_log() from public,anon;
grant execute on function public.family_request_create(uuid,text,text),public.family_request_decide(uuid,text,text,text) to authenticated,service_role;